use std::collections::HashMap;

struct Solution;

impl Solution {
    pub fn min_days(n: i32) -> i32 {
        fn dfs(n: i64, memo: &mut HashMap<i64, i32>) -> i32 {
            if n <= 1 {
                return n as i32;
            }
            if let Some(&res) = memo.get(&n) {
                return res;
            }
            // Option 1: Eat one orange, then handle n-1
            // Option 2: If divisible by 2, eat n/2 oranges in one day, so days = 1 + dfs(n/2)
            // But since we can only eat n/2 oranges if n divisible by 2, otherwise we eat some oranges to get to divisible by 2
            // Similarly for 3.
            // So we try:
            // days = 1 + min(
            //   dfs(n/2) + n%2,
            //   dfs(n/3) + n%3
            // )
            // Explanation:
            // To get to a number divisible by 2, we eat n%2 oranges one by one, then eat n/2 oranges in one day.
            // Similarly for 3.
            let res = 1 + std::cmp::min(
                dfs(n / 2, memo) + (n % 2) as i32,
                dfs(n / 3, memo) + (n % 3) as i32,
            );
            memo.insert(n, res);
            res
        }
        let mut memo = HashMap::new();
        dfs(n as i64, &mut memo)
    }
}

